<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import type {FormInstance,FormProps} from 'ant-design-vue';
import {submitForm,api,matches,pagination,showError,useActions,type Row} from './api';import PagePanel from './PagePanel.vue';import AppIcon from './AppIcon.vue';
const rows=ref<Row[]>([]),loading=ref(false),error=ref(''),search=ref(''),editorOpen=ref(false),editorLoading=ref(false),target=ref<Row|null>(null),versions=ref<Row[]>([]),formRef=ref<FormInstance>();
const fresh=()=>({code:'',name:'',steps:[{role:'db-owner',label:'数据源负责人'},{role:'dba',label:'DBA 审核'}],highRiskOnlyLast:false}),form=ref(fresh());const {busy,perform}=useActions();
const filtered=computed(()=>rows.value.filter(row=>matches(row,search.value,['name','code'])));
const rules:FormProps['rules']={name:[{required:true,message:'请输入流程名称'},{pattern:/^[\p{L}\p{N} _-]{2,80}$/u,message:'2 到 80 位文字、数字、空格、下划线或短横线'}],code:[{required:true,message:'请输入编码'},{pattern:/^[a-z][a-z0-9_-]{2,99}$/,message:'3 到 100 位小写字母、数字、下划线或短横线，须以字母开头'}]};
async function refresh(){loading.value=true;error.value='';try{rows.value=await api('/api/workflows')}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
async function edit(row?:Row){target.value=row||null;form.value={...fresh(),code:row?.code||'',name:row?.name||''};versions.value=[];editorOpen.value=true;if(row){editorLoading.value=true;try{versions.value=await api('/api/workflows/'+row.id+'/versions');const latest=versions.value[0];if(latest)form.value={code:row.code,name:row.name,steps:latest.steps.map((step:Row)=>({role:step.role,label:step.label})),highRiskOnlyLast:latest.highRiskOnlyLast}}catch(e){showError(e)}finally{editorLoading.value=false}}}
function addStep(){if(form.value.steps.length<6)form.value.steps.push({role:'review-'+(form.value.steps.length+1),label:'审批节点 '+(form.value.steps.length+1)})}
function removeStep(index:number){if(form.value.steps.length<=2)return;form.value.steps.splice(index,1);if(form.value.steps.length<3)form.value.highRiskOnlyLast=false}
function move(index:number,delta:number){const next=index+delta;if(next<0||next>=form.value.steps.length)return;[form.value.steps[index],form.value.steps[next]]=[form.value.steps[next],form.value.steps[index]]}
async function save(){const result=await perform(target.value?'/api/workflows/'+target.value.id+'/draft':'/api/workflows',form.value,'POST','流程草稿已保存');if(result){editorOpen.value=false;await refresh()}}
async function publish(row:Row){if(await perform('/api/workflows/'+row.id+'/publish',{revision:row.revision,expectedVersion:row.version},'POST','流程配置已发布'))await refresh()}
onMounted(refresh);defineExpose({refresh});
</script>
<template>
 <a-alert v-if="error" :message="error" type="error" show-icon class="dg-notice"/><div class="dg-summary dg-summary-three"><div><span>流程模板</span><strong>{{rows.length}}</strong></div><div><span>已发布配置</span><strong>{{rows.filter(r=>Number(r.publishedRevision)>0).length}}</strong></div><div><span>有新草稿</span><strong>{{rows.filter(r=>Number(r.revision)>Number(r.publishedRevision)).length}}</strong></div></div><a-alert type="warning" show-icon class="dg-notice" message="流程设计尚未接入实际审批，发布仅保存配置版本。"/>
 <PagePanel title="审批流程"><template #actions><a-button type="primary" @click="edit()"><AppIcon name="plus"/>新建流程</a-button></template><template #filters><a-input v-model:value="search" allow-clear class="dg-search" placeholder="搜索流程名称或编码" aria-label="搜索流程"><template #prefix><AppIcon name="search"/></template></a-input></template><a-table :data-source="filtered" :loading="loading" row-key="id" :pagination="pagination" :scroll="{x:800}"><a-table-column title="流程" :width="290"><template #default="{record}"><div class="dg-name-cell"><span class="dg-resource-icon"><AppIcon name="workflows"/></span><div><strong>{{record.name}}</strong><small>{{record.code}}</small></div></div></template></a-table-column><a-table-column title="最新版本"><template #default="{record}">v{{record.revision}}</template></a-table-column><a-table-column title="已发布配置版本"><template #default="{record}">{{record.publishedRevision?'v'+record.publishedRevision:'—'}}</template></a-table-column><a-table-column title="操作" align="right" :width="230"><template #default="{record}"><div class="dg-row-actions"><a-button type="link" @click="edit(record)">查看与编辑</a-button><a-button v-if="record.revision>record.publishedRevision" type="link" :disabled="busy" @click="publish(record)">发布配置</a-button></div></template></a-table-column></a-table></PagePanel>
 <a-modal v-model:open="editorOpen" :title="target?'编辑审批流程':'新建审批流程'" centered :width="800" ok-text="保存草稿" cancel-text="取消" :confirm-loading="busy" :ok-button-props="{disabled:editorLoading}" @ok="submitForm(formRef,save)"><a-spin :spinning="editorLoading"><a-form ref="formRef" :model="form" :rules="rules" layout="vertical" @finish="save"><div class="dg-form-grid"><a-form-item label="名称" name="name"><a-input v-model:value="form.name"/></a-form-item><a-form-item label="编码" name="code"><a-input v-model:value="form.code" :disabled="!!target" placeholder="例如 data-access-review"/></a-form-item></div><div class="dg-section-head"><h2>审批节点</h2><a-button size="small" :disabled="form.steps.length>=6" @click="addStep">添加节点</a-button></div><div v-for="(step,index) in form.steps" :key="index" class="dg-workflow-node"><span class="dg-node-number">{{index+1}}</span><div class="dg-node-fields"><a-form-item label="节点名称" :name="['steps',index,'label']" :rules="[{required:true,message:'请输入节点名称'},{pattern:/^[\p{L}\p{N} _-]{2,80}$/u,message:'节点名称须为 2 到 80 位文字或数字'}]"><a-input v-model:value="step.label"/></a-form-item><a-form-item label="角色编码" :name="['steps',index,'role']" :rules="[{required:true,message:'请输入角色编码'},{pattern:/^[a-z][a-z0-9_-]{2,31}$/,message:'3 到 32 位小写编码，须以字母开头'}]"><a-input v-model:value="step.role"/></a-form-item></div><div class="dg-node-actions"><a-button type="text" size="small" :disabled="index===0" @click="move(index,-1)">上移</a-button><a-button type="text" size="small" :disabled="index===form.steps.length-1" @click="move(index,1)">下移</a-button><a-button type="text" size="small" danger :disabled="form.steps.length<=2" @click="removeStep(index)">移除</a-button></div></div><a-checkbox v-model:checked="form.highRiskOnlyLast" :disabled="form.steps.length<3">最后节点仅用于高风险申请</a-checkbox></a-form><template v-if="versions.length"><div class="dg-section-head dg-top-space"><h2>版本记录</h2></div><a-table :data-source="versions" row-key="revision" :pagination="{pageSize:4}" size="small"><a-table-column title="版本" data-index="revision"/><a-table-column title="审批节点"><template #default="{record}">{{record.steps.map((step:Row)=>step.label).join(' → ')}}</template></a-table-column><a-table-column title="配置状态"><template #default="{record}">{{record.status==='PUBLISHED'?'已发布':record.status==='RETIRED'?'历史版本':'草稿'}}</template></a-table-column></a-table></template></a-spin></a-modal>
</template>
